export function convert(fromUnit: string, toUnit: string, value: number): number {
  const conversionRates: Record<string, Record<string, number>> = {
    length: { cm: 1, m: 0.01, km: 0.00001 },
    weight: { g: 1, kg: 0.001, tonne: 0.000001 },
    temperature: { celsius: 1, fahrenheit: 1.8, kelvin: 1 },
    area: { sqcm: 1, sqm: 0.0001, sqkm: 1e-8 },
    volume: { ml: 1, l: 0.001, m3: 0.000001 },
    speed: { kmh: 1, mph: 0.621371 },
    energy: { j: 1, cal: 0.239006 },
  };

  const fromCategory = fromUnit.match(/^(length|weight|temperature|area|volume|speed|energy)$/)?.[1];
  const toCategory = toUnit.match(/^(length|weight|temperature|area|volume|speed|energy)$/)?.[1];

  if (!fromCategory || !toCategory || !conversionRates[fromCategory] || !conversionRates[toCategory]) {
    throw new Error('Invalid unit category');
  }

  const fromRate = conversionRates[fromCategory][fromUnit];
  const toRate = conversionRates[toCategory][toUnit];

  if (!fromRate || !toRate) {
    throw new Error('Invalid unit');
  }

  return (value * fromRate) / toRate;
}

