  fromUnit = Object.keys(categories[cat])[0];
  toUnit = Object.keys(categories[cat])[1];
  render(container);
}

function selectUnit(unit, isFrom) {
  if (isFrom) {
    fromUnit = unit;
  } else {
    toUnit = unit;
  }
  render(container);
}

function inputValue(e) {
  value = parseFloat(e.target.value);
  render(container);
}

function convertUnits() {
  const fromCat = Object.keys(categories).find(cat => Object.keys(categories[cat]).includes(fromUnit));
  const toCat = Object.keys(categories).find(cat => Object.keys(categories[cat]).includes(toUnit));
  if (!fromCat || !toCat) {
    alert('Invalid unit');
    return;
  }
  const rate = categories[fromCat][fromUnit] / categories[toCat][toUnit];
  const converted = value * rate;
  document.getElementById('resultDisplay').textContent = `${converted.toFixed(2)} ${toUnit}`;
}

