export interface ConversionResult {
  fromValue: number;
  fromUnit: string;
  toValue: number;
  toUnit: string;
}

export function handleConversion(value: string): ConversionResult {
  try {
    const parts = value.split(' ');
    if (parts.length < 3) {
      throw new Error('Invalid format');
    }

    const fromUnit = parts[0];
    const toUnit = parts[2];
    const valueToConvert = parseFloat(parts[1]);

    if (isNaN(valueToConvert)) {
      throw new Error('Invalid value');
    }

    const convertedValue = convert(fromUnit, toUnit, valueToConvert);
    return {
      fromValue: valueToConvert,
      fromUnit,
      toValue: convertedValue,
      toUnit,
    };
  } catch (error) {
    console.error(error.message);
    throw new Error('Conversion failed');
  }
}
